import time
from datetime import datetime, timedelta, timezone
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError

CONFIG = Config(retries={'mode': 'standard', 'total_max_attempts': 3}, connect_timeout=3, read_timeout=10)


class OutOfTime(Exception):
    pass


class Budget:
    # The step's own deadline, checked before every API call.
    def __init__(self, seconds):
        self.deadline = time.time() + seconds

    def check(self):
        if time.time() >= self.deadline:
            raise OutOfTime('step deadline reached')

    def sleep(self, seconds):
        time.sleep(max(0, min(seconds, self.deadline - time.time())))


def clients(region, config=CONFIG):
    return (boto3.client('elasticache', region_name=region, config=config),
            boto3.client('resourcegroupstaggingapi', region_name=region, config=config))


def error_code(e):
    return e.response.get('Error', {}).get('Code', '') if isinstance(e, ClientError) else ''


def describe_group(ec, rg_id, b):
    b.check()
    return ec.describe_replication_groups(ReplicationGroupId=rg_id)['ReplicationGroups'][0]


def tagged_ids(tagging, key, value, b):
    # The ID of every replication group in the Region tagged key=value, from the Resource Groups
    # Tagging API, which returns a group's tags whatever its status. (ListTagsForResource fails on
    # a group that isn't available.) Any read error raises.
    ids = set()
    pages = tagging.get_paginator('get_resources').paginate(
        ResourceTypeFilters=['elasticache:replicationgroup'], TagFilters=[{'Key': key, 'Values': [value]}])
    b.check()
    for page in pages:
        for r in page.get('ResourceTagMappingList', []):
            arn = r['ResourceARN']
            if ':replicationgroup:' not in arn:
                raise Exception('Unexpected ARN from the tagging API: ' + arn)
            if any(t['Key'] == key and t['Value'] == value for t in r.get('Tags', [])):
                ids.add(arn.split(':replicationgroup:', 1)[1])
        b.check()
    return sorted(ids)


def tagged_groups(ec, tagging, key, value, b):
    # The tagged groups, and the IDs the tagging API listed that no longer exist.
    groups, gone = [], []
    for rg_id in tagged_ids(tagging, key, value, b):
        try:
            groups.append(describe_group(ec, rg_id, b))
        except ClientError as e:
            if error_code(e) != 'ReplicationGroupNotFoundFault':
                raise
            gone.append(rg_id)
    return groups, gone


def events(ec, source, kind, since, b):
    out = []
    b.check()
    for page in ec.get_paginator('describe_events').paginate(SourceIdentifier=source, SourceType=kind, StartTime=since):
        out += page['Events']
        b.check()
    return out


def names(message, cluster_id):
    return cluster_id in [w.strip('.,;:') for w in message.split()]


def is_call(message):
    return message.startswith('Test Failover API called')


def is_failover_done(message):
    return message.startswith('Failover from') and ' to replica node ' in message and 'completed' in message


def former_primary(message, members):
    # The cluster ID named before ' to replica node ' in 'Failover from primary node X to replica node Y completed'.
    for word in message.split(' to replica node ')[0].split():
        word = word.strip('.,;:')
        if word in members:
            return word
    return None


def is_recovery_done(message):
    return message.startswith('Finished recovery for cache nodes')


def is_recovering(message):
    return message.startswith('Recovering cache nodes')


def recovery_events(rg_events, node_events, cluster_id):
    # Recovery events for one node: those on its own cache cluster, and those on the group that name it.
    return node_events + [e for e in rg_events if (is_recovering(e['Message']) or is_recovery_done(e['Message']))
                          and names(e['Message'], cluster_id)]


def status_problems(ec, g, b):
    out = []
    if g['Status'] != 'available':
        out.append('group status ' + g['Status'])
    for ng in g.get('NodeGroups', []):
        n = sum(1 for m in ng.get('NodeGroupMembers', []) if m.get('CurrentRole') == 'primary')
        if n != 1:
            out.append('node group {} has {} primaries'.format(ng['NodeGroupId'], n))
    for cid in g.get('MemberClusters', []):
        b.check()
        status = ec.describe_cache_clusters(CacheClusterId=cid)['CacheClusters'][0]['CacheClusterStatus']
        if status != 'available':
            out.append('cluster {} status {}'.format(cid, status))
    return out


def event_problem(ec, g, since, b):
    # Read-only. Says why the group's events since `since` show a failover or a node recovery
    # that hasn't finished, or returns None. Each recovery is matched to the node it belongs to.
    rg_id = g['ReplicationGroupId']
    members = g.get('MemberClusters', [])
    rg_events = events(ec, rg_id, 'replication-group', since, b)
    calls = [e['Date'] for e in rg_events if is_call(e['Message'])]
    done = [e for e in rg_events if is_failover_done(e['Message'])]
    if calls and not any(d['Date'] >= max(calls) for d in done):
        return 'failover in progress'
    node_events = {c: recovery_events(rg_events, events(ec, c, 'cache-cluster', since, b), c) for c in members}
    for d in done:
        former = former_primary(d['Message'], members)
        if former is None:
            return 'cannot tell the former primary from event "{}"'.format(d['Message'])
        if not any(is_recovery_done(e['Message']) and e['Date'] >= d['Date'] for e in node_events[former]):
            return 'former primary {} recovery pending'.format(former)
    for cid, evs in node_events.items():
        rec = sorted([e for e in evs if is_recovering(e['Message']) or is_recovery_done(e['Message'])], key=lambda e: e['Date'])
        if rec and not is_recovery_done(rec[-1]['Message']):
            return 'cluster {} recovering'.format(cid)
    return None


def readiness(ec, g, since, b):
    why = []
    if g.get('ClusterEnabled'):
        why.append('cluster mode enabled (not supported)')
    if g['Status'] != 'available':
        why.append('status ' + g['Status'])
    if g.get('AutomaticFailover') != 'enabled':
        why.append('AutomaticFailover {}'.format(g.get('AutomaticFailover')))
    if g.get('MultiAZ') != 'enabled':
        why.append('MultiAZ {}'.format(g.get('MultiAZ')))
    node_groups = g.get('NodeGroups', [])
    if len(node_groups) != 1:
        why.append('{} node groups'.format(len(node_groups)))
        return why, None
    members = node_groups[0].get('NodeGroupMembers', [])
    primaries = [m['CacheClusterId'] for m in members if m.get('CurrentRole') == 'primary']
    if len(members) < 2:
        why.append('{} node(s), needs a primary and at least one replica'.format(len(members)))
    if len(primaries) != 1:
        why.append('{} primaries'.format(len(primaries)))
    if why:
        return why, None
    why += status_problems(ec, g, b)
    problem = event_problem(ec, g, since, b)
    if problem:
        why.append(problem)
    return why, (g['ReplicationGroupId'], node_groups[0]['NodeGroupId'], primaries[0])


# TestFailover fails over at most 15 node groups in a rolling 24 hours, so a run with more tagged
# groups can't finish. The cap also keeps the Targets output to the wait steps short (15 pairs of
# IDs, under 2 KB, against the 100 KB an aws:executeScript Payload holds).
MAX_GROUPS = 15

# One attempt, no retry: a retried TestFailover whose first attempt went through could start a second
# failover. total_max_attempts counts the first attempt; max_attempts 1 would allow one retry.
FAILOVER_CONFIG = Config(retries={'mode': 'standard', 'total_max_attempts': 1}, connect_timeout=3, read_timeout=30)


def ssm_client(region):
    return boto3.client('ssm', region_name=region, config=CONFIG)


def stopped_reason(ssm, execution_id, b):
    # A stop marks this step Cancelled, and the run Cancelling and then Cancelled, but doesn't end this
    # script: in testing, cancelled steps' scripts went on calling AWS for up to almost 5 minutes. So
    # read this run's own status right before each TestFailover, and call only while both the run and
    # this step are InProgress. Returns why not, or None.
    b.check()
    try:
        run = ssm.get_automation_execution(AutomationExecutionId=execution_id)['AutomationExecution']
    except Exception as e:
        return "couldn't read this run's status ({})".format(error_code(e) or e)
    status = run.get('AutomationExecutionStatus')
    step = [s.get('StepStatus') for s in run.get('StepExecutions', []) if s.get('StepName') == 'triggerFailover']
    if status != 'InProgress' or step[-1:] != ['InProgress']:
        return 'this run is {} and this step {}'.format(status, step[-1] if step else 'not listed')
    return None


def trigger_failover(events_in, context):
    b = Budget(int(events_in['timeoutSeconds']))
    ec, tagging = clients(events_in['region'])
    fo, _ = clients(events_in['region'], FAILOVER_CONFIG)
    ssm = ssm_client(events_in['region'])
    now = datetime.now(timezone.utc)
    start = (now - timedelta(seconds=10)).isoformat()
    try:
        groups, gone = tagged_groups(ec, tagging, events_in['tagKey'], events_in['tagValue'], b)
        for rg_id in gone:
            print('Listed by the tagging API but no longer exists, so not failed over: ' + rg_id)
        if not groups:
            raise Exception('Nothing failed over. No replication group found with tag {}={}.'.format(
                events_in['tagKey'], events_in['tagValue']))
        if len(groups) > MAX_GROUPS:
            raise Exception('Nothing failed over. {} replication groups have tag {}={}; TestFailover can fail over at most {} '
                            'node groups in a rolling 24 hours.'.format(len(groups), events_in['tagKey'], events_in['tagValue'], MAX_GROUPS))
        not_ready, targets = [], []
        for g in groups:
            why, target = readiness(ec, g, now - timedelta(minutes=60), b)
            if why:
                not_ready.append('{} ({})'.format(g['ReplicationGroupId'], '; '.join(why)))
            else:
                targets.append(target)
    except OutOfTime:
        raise Exception('Nothing failed over. The step deadline passed while finding and checking the tagged groups.')
    if not_ready:
        raise Exception('Nothing failed over. Tagged replication groups not ready: ' + ', '.join(not_ready))
    text = ','.join('{}={}'.format(r, f) for r, _, f in targets)
    called = []
    for rg_id, node_group, former in targets:
        try:
            # Check again right before the change: the group can have changed since the check above.
            g = describe_group(ec, rg_id, b)
            primaries = [m['CacheClusterId'] for ng in g.get('NodeGroups', []) for m in ng.get('NodeGroupMembers', []) if m.get('CurrentRole') == 'primary']
            if g['Status'] != 'available' or primaries != [former]:
                raise Exception('group changed before TestFailover: status {}, primaries {}'.format(g['Status'], primaries))
            # Last, this run's own status, because a stop doesn't end this script.
            why = stopped_reason(ssm, events_in['executionId'], b)
            if why:
                raise Exception(why)
            b.check()
        except Exception as e:
            # Everything above only reads, so this group wasn't called.
            raise Exception('TestFailover not called for {}: {}. Already failing over, and left to finish on their own: {}. Not failed over: {}'.format(
                rg_id, e, [c[0] for c in called] or 'none', [t[0] for t in targets[len(called):]]))
        try:
            fo.test_failover(ReplicationGroupId=rg_id, NodeGroupId=node_group)
        except Exception as e:
            raise Exception('TestFailover failed, or its result is unknown, for {}: {}. Already failing over, and left to finish on their own: {}. Not failed over: {}'.format(
                rg_id, e, [c[0] for c in called] or 'none', [t[0] for t in targets[len(called) + 1:]] or 'none'))
        called.append((rg_id, former))
        print('TestFailover called for {} node group {}; former primary {}'.format(rg_id, node_group, former))
    return {'Targets': text, 'StartTime': start}

