    # The step's own deadline, checked before every API call.
    def __init__(self, seconds):
        self.deadline = time.time() + seconds

    def check(self):
        if time.time() >= self.deadline:
            raise OutOfTime('step deadline reached')

    def sleep(self, seconds):
        time.sleep(max(0, min(seconds, self.deadline - time.time())))


def clients(region, config=CONFIG):
    return (boto3.client('elasticache', region_name=region, config=config),
            boto3.client('resourcegroupstaggingapi', region_name=region, config=config))


def describe_group(ec, rg_id, b):
    b.check()
    return ec.describe_replication_groups(ReplicationGroupId=rg_id)['ReplicationGroups'][0]


def events(ec, source, kind, since, b):
    out = []
    b.check()
    for page in ec.get_paginator('describe_events').paginate(SourceIdentifier=source, SourceType=kind, StartTime=since):
        out += page['Events']
        b.check()
    return out


def names(message, cluster_id):
    return cluster_id in [w.strip('.,;:') for w in message.split()]


def is_call(message):
    return message.startswith('Test Failover API called')


def is_failover_done(message):
    return message.startswith('Failover from') and ' to replica node ' in message and 'completed' in message


def former_primary(message, members):
    # The cluster ID named before ' to replica node ' in 'Failover from primary node X to replica node Y completed'.
    for word in message.split(' to replica node ')[0].split():
        word = word.strip('.,;:')
        if word in members:
            return word
    return None


def is_recovery_done(message):
    return message.startswith('Finished recovery for cache nodes')


def is_recovering(message):
    return message.startswith('Recovering cache nodes')


def recovery_events(rg_events, node_events, cluster_id):
    # Recovery events for one node: those on its own cache cluster, and those on the group that name it.
    return node_events + [e for e in rg_events if (is_recovering(e['Message']) or is_recovery_done(e['Message']))
                          and names(e['Message'], cluster_id)]


def status_problems(ec, g, b):
    out = []
    if g['Status'] != 'available':
        out.append('group status ' + g['Status'])
    for ng in g.get('NodeGroups', []):
        n = sum(1 for m in ng.get('NodeGroupMembers', []) if m.get('CurrentRole') == 'primary')
        if n != 1:
            out.append('node group {} has {} primaries'.format(ng['NodeGroupId'], n))
    for cid in g.get('MemberClusters', []):
        b.check()
        status = ec.describe_cache_clusters(CacheClusterId=cid)['CacheClusters'][0]['CacheClusterStatus']
        if status != 'available':
            out.append('cluster {} status {}'.format(cid, status))
    return out


def parse_targets(text):
    pairs = [x.split('=', 1) for x in text.split(',') if x]
    if not pairs or any(len(p) != 2 or not p[0] or not p[1] for p in pairs):
        raise Exception('Bad target list: ' + text)
    return pairs


def own_failover(ec, rg_id, former, since, b):
    # This run's failover of the group: the one 'Test Failover API called' event and the one
    # 'Failover from ... <former> to replica node ... completed' event since this run started.
    # Raises if there are more of either, since another TestFailover call then overlapped this
    # run's and its events can't be told apart. Returns (rg_events, failover event or None).
    rg_events = events(ec, rg_id, 'replication-group', since, b)
    # A copy of the same event (same message, and for a call the same time) counts once, in case the
    # group's events also carry a cache cluster's copy. Two real failovers in a row name different
    # nodes, and a second call still shows as a second 'Failover from' message or a second call.
    calls = sorted({(e['Message'], e['Date']): e for e in rg_events if is_call(e['Message'])}.values(), key=lambda e: e['Date'])
    done = {}
    for e in sorted((e for e in rg_events if is_failover_done(e['Message'])), key=lambda e: e['Date']):
        done.setdefault(e['Message'], e)
    done = list(done.values())
    if len(calls) > 1 or len(done) > 1:
        raise Exception('{} has {} TestFailover calls and {} completed failovers since this run started; another run or caller '
                        'overlapped this one, so this run cannot tell its own failover apart'.format(rg_id, len(calls), len(done)))
    if done and former_primary(done[0]['Message'], [former]) != former:
        raise Exception('The failover of {} since this run started is not from the recorded primary {}: "{}"'.format(
            rg_id, former, done[0]['Message']))
    return rg_events, (done[0] if done else None)


def gone_or_failed(g, former):
    if g['Status'] in ('deleting', 'create-failed'):
        return 'group status ' + g['Status']
    if former not in g.get('MemberClusters', []):
        return 'former primary {} is no longer a member of the group'.format(former)
    return None


def recovery_state(ec, rg_id, former, since, b):
    # None once the former primary has finished recovering after this run's failover and the
    # group and every node are available; otherwise what it's waiting for. Only recovery events
    # for the former primary count (on its own cache cluster, or on the group naming it), so
    # another node's recovery can't end the wait.
    g = describe_group(ec, rg_id, b)
    fatal = gone_or_failed(g, former)
    if fatal:
        raise Exception('Recovery of {} will not finish: {}'.format(rg_id, fatal))
    rg_events, done = own_failover(ec, rg_id, former, since, b)
    if done is None:
        raise Exception('No "Failover from ... {} ... completed" event for {} since {}'.format(former, rg_id, since.isoformat()))
    rec = [e for e in recovery_events(rg_events, events(ec, former, 'cache-cluster', since, b), former) if e['Date'] >= done['Date']]
    if not any(is_recovery_done(e['Message']) for e in rec):
        if any(is_recovering(e['Message']) for e in rec):
            return 'former primary {} recovering'.format(former)
        return 'former primary {} recovery pending'.format(former)
    issues = status_problems(ec, g, b)
    if issues:
        return 'former primary {} recovered, but {}'.format(former, '; '.join(issues))
    return None


def wait_for_recovery(events_in, context):
    b = Budget(int(events_in['timeoutSeconds']))
    ec, _ = clients(events_in['region'])
    start = datetime.fromisoformat(events_in['startTime'])
    targets = parse_targets(events_in['targets'])
    waiting = {rg_id: 'not checked yet' for rg_id, _ in targets}
    try:
        while True:
            for rg_id, former in targets:
                if rg_id not in waiting:
                    continue
                state = recovery_state(ec, rg_id, former, start, b)
                if state:
                    waiting[rg_id] = state
                else:
                    waiting.pop(rg_id)
            if not waiting:
                print('Former primary recovered for ' + ', '.join(t[0] for t in targets))
                return {'Status': 'recovered'}
            b.check()
            b.sleep(15)
    except OutOfTime:
        if events_in['failIfNotDone'] == 'true':
            raise Exception('Node recovery did not finish in time: ' + str(waiting))
        print('Still recovering, continuing in the next step: ' + str(waiting))
        return {'Status': 'still recovering'}

import time
from datetime import datetime, timedelta, timezone
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError

CONFIG = Config(retries={'mode': 'standard', 'total_max_attempts': 3}, connect_timeout=3, read_timeout=10)


class OutOfTime(Exception):
    pass


class Budget:
    # The step's own deadline, checked before every API call.
    def __init__(self, seconds):
        self.deadline = time.time() + seconds

    def check(self):
        if time.time() >= self.deadline:
            raise OutOfTime('step deadline reached')

    def sleep(self, seconds):
        time.sleep(max(0, min(seconds, self.deadline - time.time())))


def clients(region, config=CONFIG):
    return (boto3.client('elasticache', region_name=region, config=config),
            boto3.client('resourcegroupstaggingapi', region_name=region, config=config))


def error_code(e):
    return e.response.get('Error', {}).get('Code', '') if isinstance(e, ClientError) else ''


def describe_group(ec, rg_id, b):
    b.check()
    return ec.describe_replication_groups(ReplicationGroupId=rg_id)['ReplicationGroups'][0]


def tagged_ids(tagging, key, value, b):
    # The ID of every replication group in the Region tagged key=value, from the Resource Groups
    # Tagging API, which returns a group's tags whatever its status. (ListTagsForResource fails on
    # a group that isn't available.) Any read error raises.
    ids = set()
    pages = tagging.get_paginator('get_resources').paginate(
        ResourceTypeFilters=['elasticache:replicationgroup'], TagFilters=[{'Key': key, 'Values': [value]}])
    b.check()
    for page in pages:
        for r in page.get('ResourceTagMappingList', []):
            arn = r['ResourceARN']
            if ':replicationgroup:' not in arn:
                raise Exception('Unexpected ARN from the tagging API: ' + arn)
            if any(t['Key'] == key and t['Value'] == value for t in r.get('Tags', [])):
                ids.add(arn.split(':replicationgroup:', 1)[1])
        b.check()
    return sorted(ids)


def events(ec, source, kind, since, b):
    out = []
    b.check()
    for page in ec.get_paginator('describe_events').paginate(SourceIdentifier=source, SourceType=kind, StartTime=since):
        out += page['Events']
        b.check()
    return out


def names(message, cluster_id):
    return cluster_id in [w.strip('.,;:') for w in message.split()]


def is_call(message):
    return message.startswith('Test Failover API called')


def is_failover_done(message):
    return message.startswith('Failover from') and ' to replica node ' in message and 'completed' in message


def former_primary(message, members):
    # The cluster ID named before ' to replica node ' in 'Failover from primary node X to replica node Y completed'.
    for word in message.split(' to replica node ')[0].split():
        word = word.strip('.,;:')
        if word in members:
            return word
    return None


def is_recovery_done(message):
    return message.startswith('Finished recovery for cache nodes')


def is_recovering(message):
    return message.startswith('Recovering cache nodes')


def recovery_events(rg_events, node_events, cluster_id):
    # Recovery events for one node: those on its own cache cluster, and those on the group that name it.
    return node_events + [e for e in rg_events if (is_recovering(e['Message']) or is_recovery_done(e['Message']))
                          and names(e['Message'], cluster_id)]


def status_problems(ec, g, b):
    out = []
    if g['Status'] != 'available':
        out.append('group status ' + g['Status'])
    for ng in g.get('NodeGroups', []):
        n = sum(1 for m in ng.get('NodeGroupMembers', []) if m.get('CurrentRole') == 'primary')
        if n != 1:
            out.append('node group {} has {} primaries'.format(ng['NodeGroupId'], n))
    for cid in g.get('MemberClusters', []):
        b.check()
        status = ec.describe_cache_clusters(CacheClusterId=cid)['CacheClusters'][0]['CacheClusterStatus']
        if status != 'available':
            out.append('cluster {} status {}'.format(cid, status))
    return out


def event_problem(ec, g, since, b):
    # Read-only. Says why the group's events since `since` show a failover or a node recovery
    # that hasn't finished, or returns None. Each recovery is matched to the node it belongs to.
    rg_id = g['ReplicationGroupId']
    members = g.get('MemberClusters', [])
    rg_events = events(ec, rg_id, 'replication-group', since, b)
    calls = [e['Date'] for e in rg_events if is_call(e['Message'])]
    done = [e for e in rg_events if is_failover_done(e['Message'])]
    if calls and not any(d['Date'] >= max(calls) for d in done):
        return 'failover in progress'
    node_events = {c: recovery_events(rg_events, events(ec, c, 'cache-cluster', since, b), c) for c in members}
    for d in done:
        former = former_primary(d['Message'], members)
        if former is None:
            return 'cannot tell the former primary from event "{}"'.format(d['Message'])
        if not any(is_recovery_done(e['Message']) and e['Date'] >= d['Date'] for e in node_events[former]):
            return 'former primary {} recovery pending'.format(former)
    for cid, evs in node_events.items():
        rec = sorted([e for e in evs if is_recovering(e['Message']) or is_recovery_done(e['Message'])], key=lambda e: e['Date'])
        if rec and not is_recovery_done(rec[-1]['Message']):
            return 'cluster {} recovering'.format(cid)
    return None


# Fewer retries and shorter socket timeouts than the other steps: this step must report inside
# SSM's two-minute cancel window.
# At most 2 attempts of 3 s connect and 5 s read, plus up to 1 s of backoff: about 17 s.
VERIFY_CONFIG = Config(retries={'mode': 'standard', 'total_max_attempts': 2}, connect_timeout=3, read_timeout=5)


def verify_healthy(events_in, context):
    # Runs on a failure or a stop. Changes nothing: a started failover can't be undone.
    # Reports each tagged group's state, and whatever it could check by its deadline.
    b = Budget(int(events_in['timeoutSeconds']))
    ec, tagging = clients(events_in['region'], VERIFY_CONFIG)
    notes, errors = [], {}
    try:
        ids = tagged_ids(tagging, events_in['tagKey'], events_in['tagValue'], b)
    except Exception as e:
        reason = 'the step deadline passed' if isinstance(e, OutOfTime) else str(e)
        message = 'Could not find the tagged groups ({}). A started failover cannot be undone; ElastiCache completes it on its own.'.format(reason)
        print(message)
        raise Exception(message)
    gone = set()
    # The latest result for each group. A poll cut off by the deadline keeps the previous result
    # for the groups it didn't reach.
    last = {rg_id: ['not checked: the step deadline passed'] for rg_id in ids}
    errors = {}
    healthy_since = None
    while True:
        since = datetime.now(timezone.utc) - timedelta(minutes=60)
        out_of_time = False
        for rg_id in ids:
            try:
                g = describe_group(ec, rg_id, b)
                issues = status_problems(ec, g, b)
                problem = event_problem(ec, g, since, b)
                if problem:
                    issues.append(problem)
                last[rg_id] = issues
                errors.pop(rg_id, None)
            except OutOfTime:
                out_of_time = True
                break
            except ClientError as e:
                if error_code(e) != 'ReplicationGroupNotFoundFault':
                    errors[rg_id] = str(e)
                    last[rg_id] = ['could not read']
                    continue
                gone.add(rg_id)
                last[rg_id] = []
            except Exception as e:
                errors[rg_id] = str(e)
                last[rg_id] = ['could not read']
        bad = {rg_id: issues for rg_id, issues in last.items() if issues}
        if bad or errors:
            healthy_since = None
        elif healthy_since is None:
            healthy_since = time.time()
        if out_of_time or (healthy_since is not None and time.time() - healthy_since >= 30):
            break
        try:
            b.check()
        except OutOfTime:
            break
        b.sleep(10)
    if gone:
        notes.append('Listed by the tagging API but no longer exist: {}.'.format(sorted(gone)))
    if errors:
        notes.append('Could not read: {}.'.format(errors))
    note = (' ' + ' '.join(notes)) if notes else ''
    if bad or errors:
        message = 'Not healthy yet, or not checked: {}. A started failover cannot be undone; ElastiCache completes it on its own.{}'.format(bad, note)
    else:
        message = 'All {} tagged replication groups are healthy.{}'.format(len(ids) - len(gone), note)
    print(message)
    if errors:
        raise Exception(message)
    return {'Status': message}
